package com.aisla.core

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.File

/**
 * The Kotlin port must reproduce the Python reference outputs in shared/golden/
 * (generated by MediaPipe/make_golden.py from fslRecorder.py + aisl_norm.py + pandas/numpy).
 * Numbers are compared bit for bit, CSV text line for line.
 */
class GoldenTest {
    private val dir = File(System.getProperty("golden.dir") ?: "../../shared/golden")

    private fun file(name: String): File {
        val f = File(dir, name)
        assertTrue("missing golden file $f (run MediaPipe/make_golden.py)", f.isFile)
        return f
    }

    private fun d(s: String) = PyFormat.parseCell(s)

    private fun same(what: String, expected: Double, actual: Double) {
        val ok = (expected.isNaN() && actual.isNaN()) || expected.toRawBits() == actual.toRawBits()
        if (!ok) fail("$what: expected ${PyFormat.pyRepr(expected)} got ${PyFormat.pyRepr(actual)}")
    }

    private fun doubles(s: String) = s.split(' ').filter { it.isNotEmpty() }.map { d(it) }.toDoubleArray()

    // ------------------------------------------------------------------
    @Test
    fun roundingAndReprMatchPython() {
        val t = Csv.read(file("rounding.csv"))
        for (r in t.rows) {
            val x = d(r[0])
            assertEquals("repr of ${r[0]}", r[1], PyFormat.pyRepr(x))
            same("round(${r[0]}, 4)", d(r[2]), PyFormat.pyRound(x, 4))
            same("round(${r[0]}, 1)", d(r[3]), PyFormat.pyRound(x, 1))
            same("np.round(${r[0]}, 1)", d(r[4]), PyFormat.npRound(x, 1))
        }
    }

    @Test
    fun asofJoinMatchesPandasMergeAsof() {
        val t = Csv.read(file("asof.csv"))
        for (r in t.rows) {
            val left = doubles(r[t.index("left")])
            val right = doubles(r[t.index("right")])
            val tol = d(r[t.index("tolerance")])
            val dir = r[t.index("direction")]
            val expected = r[t.index("expected")].split(' ').filter { it.isNotEmpty() }.map { it.toInt() }
            val got = AsofJoin.join(left, right, dir, tol).toList()
            assertEquals("case ${r[0]} $dir", expected, got)
        }
    }

    @Test
    fun clockMapperMatchesPython() {
        val cm = ClockMapper()
        for ((i, r) in Csv.read(file("clock.csv")).rows.withIndex()) {
            same("offset row $i", d(r[2]), cm.update(d(r[0]), d(r[1])))
        }
    }

    @Test
    fun blePacketDecodeMatchesPython() {
        for (r in Csv.read(file("packets.csv")).rows) {
            val bytes = r[0].chunked(2).map { it.toInt(16).toByte() }.toByteArray()
            val p = GlovePacket.decode(bytes) ?: return fail("decode failed for ${r[0]}")
            assertEquals(r[1].toInt(), p.seq)
            same("t_dev", d(r[2]), p.tDevSec)
            for (k in 0 until 11) same("value $k of ${r[0]}", d(r[3 + k]), p.values[k])
            assertEquals(r[14].toInt(), p.flags)
        }
        assertEquals(null, GlovePacket.decode(ByteArray(20)))
    }

    @Test
    fun statsMatchNumpyAndPandas() {
        for (r in Csv.read(file("stats.csv")).rows) {
            val v = doubles(r[0])
            same("median ${r[0]}", d(r[1]), Stats.median(v))
            same("np.percentile 95 ${r[0]}", d(r[2]), Stats.percentile(v, 95.0))
            same("pd.quantile .95 ${r[0]}", d(r[3]), Stats.percentile(v, 95.0))
            same("pd.median ${r[0]}", d(r[4]), Stats.median(v))
        }
    }

    @Test
    fun handPickerMatchesPython() {
        val t = Csv.read(file("picker.csv"))
        var picker: HandPicker? = null
        for ((i, r) in t.rows.withIndex()) {
            val p = picker ?: HandPicker(r[0], r[1]).also { picker = it }
            if (r[2] == "STATS") {
                assertEquals("n_glove ${r[0]}/${r[1]}", r[4].toInt(), p.nGlove)
                assertEquals("n_label_mismatch ${r[0]}/${r[1]}", r[5].toInt(), p.nLabelMismatch)
                picker = null
                continue
            }
            val hands = r[3].split(';').filter { it.isNotEmpty() }.map { s ->
                val (label, score, x, y) = s.split(':')
                val xyz = DoubleArray(3 * N_LM)
                xyz[0] = d(x)
                xyz[1] = d(y)
                Hand(label, d(score), xyz)
            }
            val (g, o) = p.pick(hands, d(r[2]))
            assertEquals("glove pick, row ${i + 2}", r[4].toInt(), hands.indexOfFirst { it === g })
            assertEquals("other pick, row ${i + 2}", r[5].toInt(), hands.indexOfFirst { it === o })
        }
    }

    // ------------------------------------------------------------------
    private fun jsonNumber(json: String, key: String): Double {
        val m = Regex("\"$key\"\\s*:\\s*\"?([-0-9.eE+]+)\"?").find(json) ?: error("no $key")
        return d(m.groupValues[1])
    }

    private fun frameHand(cells: List<String>, at: Int): Hand? {
        if (cells[at] != "1") return null
        return Hand("Right", d(cells[at + 1]), DoubleArray(63) { d(cells[at + 2 + it]) })
    }

    private fun flatten(prefix: String, v: Any?, out: MutableList<Pair<String, String>>) {
        when (v) {
            is Map<*, *> -> v.forEach { (k, x) -> flatten(if (prefix.isEmpty()) "$k" else "$prefix.$k", x, out) }
            is List<*> -> out += prefix to v.joinToString("|")
            null -> out += prefix to "null"
            is Double -> out += prefix to PyFormat.pyRepr(v)
            else -> out += prefix to v.toString()
        }
    }

    @Test
    fun takeSyncCsvAndQualityMatchRecorder() {
        val meta = file("take_meta.json").readText()
        val tRec0 = jsonNumber(meta, "t_rec0")
        val tEnd = jsonNumber(meta, "t_end")
        val recordSec = jsonNumber(meta, "record_sec")
        val tol = jsonNumber(meta, "sync_tolerance_sec")

        val frames = Csv.read(file("take_frames_input.csv")).rows.map { c ->
            FrameRow.build(c[0].toInt(), d(c[1]), frameHand(c, 2), frameHand(c, 2 + 2 + 63), logOther = true)
        }
        val allGlove = Csv.read(file("take_glove_input.csv")).rows.map { c ->
            GloveSample(d(c[0]), DoubleArray(11) { d(c[1 + it]) }, d(c[12]), c[13].toInt(), c[14].toInt())
        }
        val window = allGlove.filter { it.t >= tRec0 - tol && it.t <= tEnd + tol }
        val perf = Csv.read(file("take_perf_input.csv")).rows.map { Quality.Perf(d(it[0]), it[1].toInt()) }

        val rows = TakeSync.sync(frames, window, tRec0, "nearest", tol)

        // 1) every number
        val (header, expected) = Csv.readNumbers(file("take_expected.csv"))
        assertEquals(TakeSchema.outputColumns(true), header)
        assertEquals(expected.size, rows.size)
        for (i in rows.indices) {
            val got = rows[i].values()
            for (k in header.indices) same("take row $i ${header[k]}", expected[i][k], got[k])
        }
        // 2) the CSV text itself (pandas to_csv vs TakeSync.writeCsv)
        val sb = StringBuilder()
        TakeSync.writeCsv(sb, rows, logOther = true)
        assertEquals(file("take_expected.csv").readLines(), sb.toString().lines().dropLast(1))

        // 3) quality stats
        val q = Quality.compute(rows, window, tRec0, recordSec, perf,
            linkedMapOf("mode" to "assume", "mediapipe_label_mismatch_frac" to 0.0))
        val flat = mutableListOf<Pair<String, String>>()
        flatten("", q, flat)
        val exp = Csv.read(file("take_quality_expected.csv")).rows.map { it[0] to it[1] }
        assertEquals(exp, flat)
    }

    /** "flex_calibration": {"open": [..], "closed": [..]} from a take JSON, or null. */
    private fun flexCalFromJson(json: String): FlexCalibration? {
        val block = Regex("\"flex_calibration\"\\s*:\\s*\\{[^}]*\\}").find(json)?.value ?: return null
        fun arr(key: String) = Regex("\"$key\"\\s*:\\s*\\[([^\\]]*)\\]").find(block)!!.groupValues[1]
            .split(',').map { d(it.trim()) }.toDoubleArray()
        return FlexCalibration(arr("open"), arr("closed"))
    }

    @Test
    fun flexCalibrationMatchesPython() {
        val t = Csv.read(file("flex_calibration.csv"))
        var ok = 0
        for (r in t.rows) {
            fun samples(s: String) = s.split('|').map { doubles(it) }
            val result = try {
                FlexCalibration.fromSamples(samples(r[1]), samples(r[2]))
            } catch (e: IllegalArgumentException) {
                assertEquals("case ${r[0]}", "error", r[3])
                assertEquals("case ${r[0]} message", r[4], e.message!!.replace(",", ";"))
                null
            } ?: continue
            assertEquals("case ${r[0]}", "ok", r[3])
            val o = doubles(r[4])
            val c = doubles(r[5])
            for (i in 0 until 5) {
                same("case ${r[0]} open F${i + 1}", o[i], result.open[i])
                same("case ${r[0]} closed F${i + 1}", c[i], result.closed[i])
            }
            val probe = result.normalize(doubles(r[6]))
            val exp = doubles(r[7])
            for (i in 0 until 5) same("case ${r[0]} normalized F${i + 1}", exp[i], probe[i])
            ok++
        }
        assertTrue("no successful calibration cases", ok > 0)
    }

    @Test
    fun takeColumnLayoutMatchesRecorder() {
        for (logOther in listOf(true, false)) {
            val expected = file("columns_log_other_${if (logOther) "True" else "False"}.csv").readLines()[0].split(',')
            assertEquals("log_other=$logOther", expected, TakeSchema.outputColumns(logOther))
        }
        assertEquals(79, TakeSchema.outputColumns(false).size)
        assertEquals(79, Normalizer.FEATURE_COLUMNS.size)
    }

    @Test
    fun normalizerMatchesAislNorm() {
        val inputs = File(dir, "norm_inputs").listFiles { f -> f.name.endsWith(".csv") }?.sortedBy { it.name }
        assertTrue("no norm inputs", !inputs.isNullOrEmpty())
        for (csv in inputs!!) {
            val json = File(csv.path.removeSuffix(".csv") + ".json").readText()
            val block = Regex("\"mediapipe_input\"\\s*:\\s*\\{[^}]*\\}").find(json)?.value
                ?: Regex("\"camera_reported\"\\s*:\\s*\\{[^}]*\\}").find(json)!!.value
            val w = jsonNumber(block, "width")
            val h = jsonNumber(block, "height")
            val (header, rows) = Csv.readNumbers(csv)
            val out = Normalizer.normalizeTake(header, rows, w, h, flexCalFromJson(json))

            val expFile = File(dir, "norm_expected/${csv.nameWithoutExtension}_norm.csv")
            val (eh, exp) = Csv.readNumbers(expFile)
            assertEquals(Normalizer.FEATURE_COLUMNS, eh)
            assertEquals(exp.size, out.size)
            for (i in out.indices) for (k in eh.indices) {
                same("${csv.name} step $i ${eh[k]}", exp[i][k], out[i][k])
            }
            val sb = StringBuilder()
            Normalizer.writeCsv(sb, out)
            assertEquals(expFile.readLines(), sb.toString().lines().dropLast(1))
        }
    }

    @Test
    fun takeRecorderTiming() {
        val rec = TakeRecorder(recordSec = 4.0, countdownSec = 3.0)
        rec.start(100.0)                     // recording window = [103, 107)
        var t = 100.0
        var finished: TakeRecorder.Status.Finished? = null
        var countdown = 0
        while (finished == null) {
            t += 1.0 / 30
            when (val s = rec.onFrame(t, null, null, 10.0, 1)) {
                is TakeRecorder.Status.Countdown -> countdown++
                is TakeRecorder.Status.Finished -> finished = s
                else -> {}
            }
        }
        val f = finished!!
        assertTrue(countdown in 89..90)
        assertTrue(f.rows.size in 119..121)
        // t_sec is round(t_rec, 4): a frame at 3.99999.. s is stored as 4.0, exactly like Python
        assertTrue(f.rows.all { it.tSec >= 0.0 && it.tSec <= 4.0 })
        assertEquals(0, f.perf[0].skipped)    // first frame never counts as skipped
        assertEquals(1, f.perf[1].skipped)
        assertTrue(f.tEnd - f.tRec0 >= 4.0)
    }
}
